<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('PreventionControl/index')}">公共场所防控二维码列表</a>				    <a class="on">【{pigcms{$info['name']}】二维码填写记录</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('PreventionControl/user_index')}" method="get">							<input type="hidden" name="c" value="PreventionControl"/>							<input type="hidden" name="a" value="user_index"/>							<input type="hidden" name="id" value="{pigcms{$_GET['id']}"/>							名称: 							<input type="text" name="name" class="input-text" value="{pigcms{$_GET['name']}"/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;							电话: 							<input type="text" name="phone" class="input-text" value="{pigcms{$_GET['phone']}"/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;							<input type="submit" value="查询" class="button"/>							<a href="javascript:void(0)" onclick="location.href='{pigcms{:U('user_export',$_GET)}'" class="button" style="float:right;margin-right: 100px;">导出</a>						</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<style>					.table-list td{line-height:22px;padding-top:5px;padding-bottom:5px;}					</style>					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>						</colgroup>						<thead>							<tr>								<th>编号</th>								<th>名称</th>								<th>联系电话</th>								<if condition="$info['type'] eq 0 || $info['type'] eq 2">									<th>上车地点</th>									<th>下车地点</th>								<else/>									<th>住址</th>									<th>体温</th>								</if>																<th>备注信息</th>								<if condition="$info['type'] eq 0 || $info['type'] eq 2">									<th>上车时间</th>									<th>下车时间</th>								<else/>									<th>登记时间</th>								</if>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td>{pigcms{$vo.name}</td>										<td>{pigcms{$vo.phone}</td>										<if condition="$info['type'] eq 0 || $info['type'] eq 2">											<td>{pigcms{$vo.start_address}</td>											<td>{pigcms{$vo.end_address}</td>										<else/>											<td>{pigcms{$vo.address}</td>											<td>{pigcms{$vo.temp}</td>										</if>										<td>{pigcms{$vo.remark}</td>										<if condition="$info['type'] eq 0 || $info['type'] eq 2">											<td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>											<td>												<if condition="$vo['last_time']">													{pigcms{$vo.last_time|date='Y-m-d H:i:s',###}												<else/>													-												</if>											</td>										<else/>											<td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>										</if>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>